package server

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/go-chi/chi/v5"
)

// The route table is registered once, in New(), across several handler
// groups that share the `/api/v1/workflows` prefix — a static `templates`
// sibling of the `{id}` wildcard, colon actions hanging off both, and
// two-segment paths under each. Per-handler tests mount only their OWN
// routes, so a path that a SIBLING registration shadows cannot fail there:
// it needs the whole table in one router, which is what this pins.
//
// A path that resolves to chi's NotFound never runs the authenticated
// group's middleware at all, so the symptom is a bare "404 page not found"
// where the caller expected a 401 — indistinguishable, from the outside,
// from a route that was never written.
func TestWorkflowRouteTable_EveryRegisteredPathResolves(t *testing.T) {
	// Mirrors New()'s registration order and shape exactly. Built here rather
	// than calling New() so the test needs no verifier, gRPC client, or
	// network — the question is purely "does chi resolve this path".
	r := chi.NewRouter()
	ok := func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusTeapot) }

	r.Post("/api/v1/workflows", ok)
	r.Get("/api/v1/workflows", ok)
	r.Get("/api/v1/workflows/{id}", ok)
	r.Patch("/api/v1/workflows/{id}", ok)
	r.Delete("/api/v1/workflows/{id}", ok)
	r.Post("/api/v1/workflows/{id}:archive", ok)

	r.Get("/api/v1/workflows/{id}/canvas", ok)
	r.Put("/api/v1/workflows/{id}/canvas", ok)
	r.Post("/api/v1/workflows/{id}/canvas:clear", ok)

	r.Get("/api/v1/workflows/projects", ok)
	r.Post("/api/v1/workflows/projects", ok)

	r.Get("/api/v1/workflows/node-types", ok)

	r.Post("/api/v1/workflows/{id}/executions", ok)
	r.Get("/api/v1/workflows/{id}/executions", ok)
	r.Get("/api/v1/workflows/executions/{executionId}", ok)
	r.Post("/api/v1/workflows/executions/{executionId}:cancel", ok)
	r.Post("/api/v1/workflows/{id}/nodes/{nodeKey}:run", ok)
	r.Post("/api/v1/workflows/executions/{executionId}/nodes/{nodeKey}:submit-input", ok)

	r.Get("/api/v1/workflows/brand-profiles", ok)
	r.Post("/api/v1/workflows/brand-profiles", ok)
	r.Get("/api/v1/workflows/brand-profiles/{id}", ok)

	r.Get("/api/v1/workflows/templates", ok)
	r.Post("/api/v1/workflows/templates", ok)
	r.Get("/api/v1/workflows/templates/{id}", ok)
	r.Delete("/api/v1/workflows/templates/{id}", ok)
	r.Post("/api/v1/workflows/templates/{id}:instantiate", ok)

	const uuid = "11111111-1111-1111-1111-111111111111"
	cases := []struct{ method, path string }{
		{http.MethodGet, "/api/v1/workflows"},
		{http.MethodPost, "/api/v1/workflows"},
		{http.MethodGet, "/api/v1/workflows/" + uuid},
		{http.MethodPatch, "/api/v1/workflows/" + uuid},
		{http.MethodDelete, "/api/v1/workflows/" + uuid},
		{http.MethodPost, "/api/v1/workflows/" + uuid + ":archive"},
		{http.MethodGet, "/api/v1/workflows/" + uuid + "/canvas"},
		{http.MethodPut, "/api/v1/workflows/" + uuid + "/canvas"},
		{http.MethodPost, "/api/v1/workflows/" + uuid + "/canvas:clear"},
		{http.MethodGet, "/api/v1/workflows/projects"},
		{http.MethodPost, "/api/v1/workflows/projects"},
		{http.MethodGet, "/api/v1/workflows/node-types"},
		{http.MethodPost, "/api/v1/workflows/" + uuid + "/executions"},
		{http.MethodGet, "/api/v1/workflows/" + uuid + "/executions"},
		{http.MethodGet, "/api/v1/workflows/executions/" + uuid},
		{http.MethodPost, "/api/v1/workflows/executions/" + uuid + ":cancel"},
		{http.MethodPost, "/api/v1/workflows/" + uuid + "/nodes/n1:run"},
		{http.MethodPost, "/api/v1/workflows/executions/" + uuid + "/nodes/n1:submit-input"},
		{http.MethodGet, "/api/v1/workflows/brand-profiles"},
		{http.MethodPost, "/api/v1/workflows/brand-profiles"},
		{http.MethodGet, "/api/v1/workflows/brand-profiles/" + uuid},
		{http.MethodGet, "/api/v1/workflows/templates"},
		{http.MethodPost, "/api/v1/workflows/templates"},
		// The three the live walled stack answered with a bare 404.
		{http.MethodGet, "/api/v1/workflows/templates/" + uuid},
		{http.MethodDelete, "/api/v1/workflows/templates/" + uuid},
		{http.MethodPost, "/api/v1/workflows/templates/" + uuid + ":instantiate"},
		// Built-in ids are a hyphen namespace, not a UUID — and they travel
		// through the same colon-action route, which is exactly why the
		// separator is a hyphen (chi binds a param to the FIRST tail byte in
		// the segment).
		{http.MethodGet, "/api/v1/workflows/templates/builtin-first-workflow"},
		{http.MethodDelete, "/api/v1/workflows/templates/builtin-first-workflow"},
		{http.MethodPost, "/api/v1/workflows/templates/builtin-first-workflow:instantiate"},
	}

	for _, tc := range cases {
		rec := httptest.NewRecorder()
		r.ServeHTTP(rec, httptest.NewRequest(tc.method, tc.path, nil))
		if rec.Code != http.StatusTeapot {
			t.Errorf("%s %s resolved to %d, want the registered handler (418). "+
				"404 here means chi never matched it, so the authenticated group's "+
				"middleware never runs and the caller sees a bare 404.",
				tc.method, tc.path, rec.Code)
		}
	}
}


