package server

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

// TestNewRouter_SetsSecurityHeaders pins the lone-sibling gap found in the
// T19 retrofit audit: 10 of 13 BFFs mount platform/libs/go/security.Middleware
// on their router; workflow-bff did not. This test hits the always-registered
// /healthz route (no downstream / no JWT required) and asserts the four
// day-1 security headers are present with their canonical values (mirrored
// from platform/libs/go/security/headers_test.go and admin-bff's
// security_headers_test.go).
func TestNewRouter_SetsSecurityHeaders(t *testing.T) {
	h := New(Deps{})

	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/healthz", nil)
	h.ServeHTTP(rec, req)

	if got := rec.Header().Get("X-Content-Type-Options"); got != "nosniff" {
		t.Errorf("X-Content-Type-Options = %q, want %q — security.Middleware not applied", got, "nosniff")
	}
	if got := rec.Header().Get("X-Frame-Options"); got != "DENY" {
		t.Errorf("X-Frame-Options = %q, want %q — security.Middleware not applied", got, "DENY")
	}
	if got := rec.Header().Get("Strict-Transport-Security"); got != "max-age=31536000; includeSubDomains" {
		t.Errorf("Strict-Transport-Security = %q, want %q — security.Middleware not applied", got, "max-age=31536000; includeSubDomains")
	}
	if got := rec.Header().Get("Referrer-Policy"); got != "strict-origin-when-cross-origin" {
		t.Errorf("Referrer-Policy = %q, want %q — security.Middleware not applied", got, "strict-origin-when-cross-origin")
	}
}


--- services/workflow-bff/internal/server/server.go (412 lines) ---
// Package server holds the HTTP router for workflow-bff.
//
// Retrofitted (T21, epic #2431) onto platform/libs/go/bffserver: this
// router's shape — root chassis, /healthz + /readyz, and a single
// authenticated route group with the standard 5-middleware chain — is an
// exact match for the shared bffserver.NewRouter/Authenticated skeleton, so
// New below is now a thin composition of the two rather than a hand-rolled
// copy. workflow-bff is the REST→gRPC trust boundary in front of
// workflow-svc: every authenticated route validates the user JWT
// (auth.HTTPMiddleware) and the handlers mint + forward the platform x-*
// headers from validated claims onto the gRPC call (auth.ForwardingContext).
//
// Public health probes (/healthz, /readyz) sit OUTSIDE the auth + rate-limit
// group. The WorkflowService Get/List routes prove the REST→gRPC hop;
// Create/Update/SetStatus/Delete land in later workflow sub-PRs.
package server

import (
	"log/slog"
	"net/http"
	"net/netip"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/httprate"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/bffserver"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/featureflags"
	"github.com/zenithflowinc/omnicore-platform/services/workflow-bff/internal/dialogueclient"
	"github.com/zenithflowinc/omnicore-platform/services/workflow-bff/internal/filesclient"
	"github.com/zenithflowinc/omnicore-platform/services/workflow-bff/internal/handlers"
	"github.com/zenithflowinc/omnicore-platform/services/workflow-bff/internal/workflowclient"
)

// authenticatedGroupTimeout bounds total request duration on every route in
// the authenticated group, INCLUDING POST .../nodes/{nodeKey}:run (RunNode).
// RunNode sets its own explicit 35s context.WithTimeout at the handler
// (internal/handlers/execution.go's runNodeDeadline) — deliberately longer
// than workflowclient.Dial's TierDefault (30s) fallback, since a single
// node's synchronous execution legitimately runs longer than an ordinary
// CRUD call. 45s here gives that 35s deadline 10s of headroom to fire and
// be mapped to an HTTP error before this HTTP-level Timeout would otherwise
// fire first — the group Timeout only ever wraps a LONGER-lived context, it
// never truncates RunNode's own deadline (nested context.WithTimeout always
// resolves to the SHORTER of the two). No route in this service streams
// (Flusher/SSE/multipart) — see the Task 5 audit — so a single group-wide
// Timeout is safe with no per-route exemption needed.
//
// A var, not a const: tests shrink it to keep a wedged-downstream test fast
// and immune to httpserver.Timeout's process-wide OMNICORE_TIMEOUT_SCALE
// cache (which locks in at the first Timeout() call across this whole test
// binary, not per-test).
var authenticatedGroupTimeout = 45 * time.Second

// Stater is an alias for bffserver.Stater, kept so existing call sites
// (Deps.WorkflowClient's type, any external reference to server.Stater)
// don't need to change.
type Stater = bffserver.Stater

// Deps groups the runtime dependencies the router needs.
type Deps struct {
	// MetricsHandler serves the Prometheus /metrics scrape endpoint (PUBLIC).
	// MetricsMiddleware wraps the entire router to record every request.
	// Both are set by main.go via observability after SetupMeter.
	MetricsHandler    http.Handler
	MetricsMiddleware func(http.Handler) http.Handler

	// Logger backs the fail-soft warning paths (a failed identity lookup on
	// the share roster). OPTIONAL: nil silences those warnings, never fails a
	// request.
	Logger *slog.Logger

	Verifier *auth.JWTVerifier
	// WorkflowClient supplies the connectivity state for /readyz.
	WorkflowClient Stater
	// WorkflowTypedClient is the full workflowclient.Client used to construct
	// the workflow, canvas, project, and node-catalog handlers. Kept separate
	// from WorkflowClient so tests that only need /healthz + /readyz can pass
	// a nil typed client.
	WorkflowTypedClient *workflowclient.Client

	// DialogueTypedClient serves the Broadcast node's config pickers (#1394).
	// OPTIONAL and deliberately not part of /readyz: nil (no DIALOGUE_SVC_ADDR)
	// leaves the four picker routes unregistered, and every other workflow
	// route is unaffected. See internal/dialogueclient for the auth posture.
	DialogueTypedClient *dialogueclient.Client

	// FilesTypedClient serves the Files & Data nodes' config pickers (#1407).
	// OPTIONAL and deliberately not part of /readyz, for the same reason as
	// DialogueTypedClient above: nil (no FILES_SVC_ADDR) leaves the three
	// picker routes unregistered and every other workflow route unaffected.
	// See internal/filesclient for the auth posture — these reads forward the
	// caller's own token, unlike the worker's write hop.
	FilesTypedClient *filesclient.Client

	// FeatureFlagCache is an optional TTL-backed feature-flag cache. When
	// non-nil, RequireVerticalEnabled("workflows") is mounted on the
	// authenticated route group and returns 403 vertical_disabled when
	// org-svc reports the workflows vertical is disabled. A nil cache is a
	// pass-through no-op (fail-safe-open for local dev when org-svc is not
	// wired).
	FeatureFlagCache *featureflags.Cache

	// OrgRoleReader resolves the caller's org-membership role on the run-start
	// route (#1394) by reading their own org's roster. OPTIONAL and
	// fail-closed: nil (no ORG_SVC_ADDR) means every run records an empty
	// role, and a Broadcast node inside it is denied by dialogue-svc's
	// curation gate. Satisfied by *orgclient.Client.
	OrgRoleReader handlers.OrgRosterReader

	// WorkflowH, CanvasH, ProjectH, NodeCatalogH, ExecutionH, BrandProfileH,
	// TemplateH, DialogueH, FilesH may be injected directly by tests (without
	// a live gRPC client). When non-nil they take precedence over the handlers
	// built from the typed client.
	WorkflowH     *handlers.WorkflowHandler
	CanvasH       *handlers.CanvasHandler
	ProjectH      *handlers.ProjectHandler
	NodeCatalogH  *handlers.NodeCatalogHandler
	ExecutionH    *handlers.ExecutionHandler
	BrandProfileH *handlers.BrandProfileHandler
	TemplateH     *handlers.TemplateHandler
	TriggerH      *handlers.TriggerHandler
	DialogueH     *handlers.DialogueHandler
	FilesH        *handlers.FilesHandler
	OrgMembersH   *handlers.OrgMembersHandler

	// UserLookup hydrates the project share roster (#1355) with display names
	// and emails. OPTIONAL and fail-soft: nil (no IDENTITY_SVC_ADDR) means the
	// roster still serves, with raw user ids. Satisfied by
	// *platform/libs/go/identityclient.Client.
	UserLookup handlers.UserProfileLookup

	// QueueAccountsH backs GET /api/v1/workflows/queue-accounts (#1390's
	// Add to Queue target-account picker). Unlike the handlers above it is
	// NOT built from WorkflowTypedClient — it proxies to queue-svc, a
	// different vertical — so main.go constructs it directly, and passes a
	// handler wrapping a nil client when QUEUE_SVC_ADDR is unset. The route
	// mounts unconditionally either way: a clean 503 beats a 404 that reads
	// as a routing bug.
	QueueAccountsH *handlers.QueueAccountsHandler

	// TrustedProxyCIDRs is the set of CIDR ranges trusted to supply a
	// truthful X-Forwarded-For / True-Client-IP chain, consumed by
	// security.ClientIPMiddleware. A request whose immediate peer
	// (RemoteAddr) falls outside this set has its client IP resolved from
	// RemoteAddr alone — any forged forwarding header is ignored.
	TrustedProxyCIDRs []netip.Prefix
}

// New returns a chi.Router wired with middleware + /healthz + /readyz + the
// authenticated WorkflowService route group.
func New(deps Deps) http.Handler {
	r := bffserver.NewRouter(bffserver.Options{
		Verifier:          deps.Verifier,
		TrustedProxyCIDRs: deps.TrustedProxyCIDRs,
		Stater:            deps.WorkflowClient,
		MetricsHandler:    deps.MetricsHandler,
		MetricsMiddleware: deps.MetricsMiddleware,
		FeatureFlagCache:  deps.FeatureFlagCache,
	})

	// Resolve the handler instances. Prefer directly injected handlers
	// (tests); fall back to building from the typed gRPC client.
	workflowH := deps.WorkflowH
	canvasH := deps.CanvasH
	projectH := deps.ProjectH
	nodeCatalogH := deps.NodeCatalogH
	executionH := deps.ExecutionH
	brandProfileH := deps.BrandProfileH
	templateH := deps.TemplateH
	triggerH := deps.TriggerH
	orgMembersH := deps.OrgMembersH
	if orgMembersH == nil && deps.OrgRoleReader != nil {
		if lister, ok := deps.OrgRoleReader.(handlers.OrgRosterLister); ok {
			orgMembersH = handlers.NewOrgMembersHandler(lister, deps.UserLookup, deps.Logger)
		}
	}
	if deps.WorkflowTypedClient != nil {
		if workflowH == nil {
			workflowH = handlers.NewWorkflowHandler(deps.WorkflowTypedClient.Workflows)
		}
		if canvasH == nil {
			// CanvasHandler resolves workflow_id -> canvas_id via
			// WorkflowService.Get, so it needs the workflow client too.
			canvasH = handlers.NewCanvasHandler(deps.WorkflowTypedClient.Canvases, deps.WorkflowTypedClient.Workflows)
		}
		if projectH == nil {
			projectH = handlers.NewProjectHandlerWithLookup(
				deps.WorkflowTypedClient.Projects, deps.UserLookup, deps.Logger,
			)
		}
		if nodeCatalogH == nil {
			nodeCatalogH = handlers.NewNodeCatalogHandler(deps.WorkflowTypedClient.NodeCatalog)
		}
		if executionH == nil {
			executionH = handlers.NewExecutionHandler(deps.WorkflowTypedClient.Executions)
		}
		if brandProfileH == nil {
			brandProfileH = handlers.NewBrandProfileHandler(deps.WorkflowTypedClient.BrandProfiles)
		}
		if templateH == nil {
			templateH = handlers.NewTemplateHandler(deps.WorkflowTypedClient.Templates)
		}
		if triggerH == nil {
			triggerH = handlers.NewTriggerHandler(deps.WorkflowTypedClient.Triggers)
		}
	}
	// Dialogue is an OPTIONAL dependency (#1394): built from its own client,
	// not WorkflowTypedClient, so an unset DIALOGUE_SVC_ADDR simply leaves the
	// picker routes unregistered. Every other workflow route still works.
	dialogueH := deps.DialogueH
	if dialogueH == nil && deps.DialogueTypedClient != nil {
		dialogueH = handlers.NewDialogueHandler(
			deps.DialogueTypedClient.Channels,
			deps.DialogueTypedClient.ContactGroups,
			deps.DialogueTypedClient.Tags,
			deps.DialogueTypedClient.Contacts,
		)
	}

	// Files is an OPTIONAL dependency (#1407) on the same terms as Dialogue
	// above: its own client, so an unset FILES_SVC_ADDR leaves only the picker
	// routes unregistered.
	filesH := deps.FilesH
	if filesH == nil && deps.FilesTypedClient != nil {
		filesH = handlers.NewFilesHandler(
			deps.FilesTypedClient.Corpora,
			deps.FilesTypedClient.Documents,
		)
	}

	// Webhook trigger invoke (#1343) — OUTSIDE the JWT auth group,
	// mirroring dialogue-bff's inbound webhook routes (server.go's own
	// comment there: "Telegram webhook ingest — OUTSIDE the JWT auth
	// group"). The caller is an external system with no user session; the
	// path-embedded `secret` IS the auth, validated by workflow-svc's
	// TriggerService.InvokeWebhook (the one gRPC RPC that bypasses its own
	// JWT interceptor for the same reason). Rate-limited by IP alone (no
	// tenant/org context exists pre-auth) so a leaked or brute-forced
	// secret can't be hammered into a DoS vector.
	if triggerH != nil {
		r.With(httprate.LimitByIP(30, time.Minute)).
			Post("/api/v1/workflows/webhooks/{triggerId}/{secret}", triggerH.Invoke)
	}

	// Authenticated, rate-limited routes.
	bffserver.Authenticated(r, bffserver.Options{
		Verifier:         deps.Verifier,
		FeatureFlagCache: deps.FeatureFlagCache,
		Vertical:         "workflows",
		RequestTimeout:   authenticatedGroupTimeout,
	}, func(r chi.Router) {
		if workflowH != nil {
			r.Post("/api/v1/workflows", workflowH.Create)
			r.Get("/api/v1/workflows", workflowH.List)
			r.Get("/api/v1/workflows/{id}", workflowH.Get)
			r.Patch("/api/v1/workflows/{id}", workflowH.Update)
			r.Delete("/api/v1/workflows/{id}", workflowH.Delete)
			// chi treats ":" as a literal character in route patterns, so
			// /workflows/{id}:archive is a distinct route from
			// /workflows/{id} and must be registered as a full path
			// (mirrors range-bff's colon-action registration pattern).
			r.Post("/api/v1/workflows/{id}:archive", workflowH.Archive)
		}

		if canvasH != nil {
			r.Get("/api/v1/workflows/{id}/canvas", canvasH.GetCanvas)
			r.Put("/api/v1/workflows/{id}/canvas", canvasH.SaveCanvas)
			// chi treats ":" as a literal character, so
			// /workflows/{id}/canvas:clear is a distinct route from
			// /workflows/{id}/canvas.
			r.Post("/api/v1/workflows/{id}/canvas:clear", canvasH.ClearCanvas)
		}

		if projectH != nil {
			r.Get("/api/v1/workflows/projects", projectH.List)
			r.Post("/api/v1/workflows/projects", projectH.Create)
			// `projects` is a literal segment and chi is trie-based, so these
			// never collide with /api/v1/workflows/{id} — the same
			// static-beats-param precedence /node-types and /executions/
			// already rely on. Pinned by a router test rather than left to
			// registration order.
			r.Get("/api/v1/workflows/projects/{id}", projectH.Get)
			r.Get("/api/v1/workflows/projects/{id}/workflows", projectH.ListWorkflows)
			r.Get("/api/v1/workflows/projects/{id}/members", projectH.ListMembers)
			// The project WRITE routes resolve the caller's org role, so
			// workflow-svc's access check can honour its org OWNER/ADMIN
			// branch (#1355). Scoped to writes only: it costs an org-svc round
			// trip and no read consumes a role.
			r.With(handlers.ResolveOrgRole(deps.OrgRoleReader)).Group(func(r chi.Router) {
				r.Patch("/api/v1/workflows/projects/{id}", projectH.Update)
				r.Delete("/api/v1/workflows/projects/{id}", projectH.Delete)
				r.Put("/api/v1/workflows/projects/{id}/members/{userId}", projectH.SetMember)
				r.Delete("/api/v1/workflows/projects/{id}/members/{userId}", projectH.RemoveMember)
			})
		}

		if orgMembersH != nil {
			// The share picker's candidate list (#1355). Under
			// /workflows/org/ rather than /workflows/{id}/ — it is org-scoped,
			// not workflow-scoped.
			r.Get("/api/v1/workflows/org/members", orgMembersH.List)
		}

		if nodeCatalogH != nil {
			r.Get("/api/v1/workflows/node-types", nodeCatalogH.ListNodeTypes)
			if deps.QueueAccountsH != nil {
				r.Get("/api/v1/workflows/queue-accounts", deps.QueueAccountsH.List)
			}
		}

		if workflowH != nil {
			// The org's tag vocabulary (#1356), backing the filter bar and the
			// chip input's autocomplete.
			r.Get("/api/v1/workflows/tags", workflowH.ListTags)
		}

		if executionH != nil {
			// Start ALONE resolves the caller's org role, so workflow-svc can
			// pin it to the run for a Broadcast node to forward later (#1394).
			// Scoped to this one route: it costs an org-svc round trip, and no
			// other workflow route consumes a role.
			r.With(handlers.ResolveOrgRole(deps.OrgRoleReader)).
				Post("/api/v1/workflows/{id}/executions", executionH.Start)
			r.Get("/api/v1/workflows/{id}/executions", executionH.List)
			// Get + Cancel are addressed by execution id under the static
			// /executions/ segment (a sibling of the {id} wildcard — chi
			// matches the static segment first, the same static-vs-param
			// precedence the /projects + /node-types routes already rely on).
			r.Get("/api/v1/workflows/executions/{executionId}", executionH.Get)
			// chi treats ":" as a literal, so :cancel / :run are distinct
			// routes and must be registered as full paths (mirrors the
			// :archive / :clear colon-action registration above).
			r.Post("/api/v1/workflows/executions/{executionId}:cancel", executionH.Cancel)
			r.Post("/api/v1/workflows/{id}/nodes/{nodeKey}:run", executionH.RunNode)
			// #1402 PR C — satisfy a parked manual_input gate. node_key rides the
			// path, mirroring :run above.
			r.Post(
				"/api/v1/workflows/executions/{executionId}/nodes/{nodeKey}:submit-input",
				executionH.SubmitNodeInput,
			)
		}

		if brandProfileH != nil {
			r.Get("/api/v1/workflows/brand-profiles", brandProfileH.List)
			r.Post("/api/v1/workflows/brand-profiles", brandProfileH.Save)
			r.Get("/api/v1/workflows/brand-profiles/{id}", brandProfileH.Get)
		}

		if templateH != nil {
			// /templates is a static sibling of the /{id} wildcard — chi
			// matches the static segment first, the same precedence the
			// /projects + /node-types + /brand-profiles routes already
			// rely on.
			r.Get("/api/v1/workflows/templates", templateH.List)
			r.Post("/api/v1/workflows/templates", templateH.Save)
			r.Get("/api/v1/workflows/templates/{id}", templateH.Get)
			r.Delete("/api/v1/workflows/templates/{id}", templateH.Delete)
			// chi treats ":" as a literal, so :instantiate is a distinct
			// route and must be registered as a full path (mirrors the
			// :archive / :clear / :cancel colon-action registrations above).
			r.Post("/api/v1/workflows/templates/{id}:instantiate", templateH.Instantiate)
		}

		if triggerH != nil {
			r.Get("/api/v1/workflows/{id}/triggers", triggerH.List)
			r.Post("/api/v1/workflows/{id}/triggers", triggerH.Create)
			// Addressed by trigger id under the static /triggers/ segment — a
			// sibling of the {id} wildcard, same static-vs-param precedence
			// /projects, /node-types, /templates etc. already rely on.
			r.Patch("/api/v1/workflows/triggers/{triggerId}", triggerH.Update)
			// chi treats ":" as a literal, so :disable/:enable are distinct
			// routes and must be registered as full paths (mirrors :archive /
			// :clear / :cancel / :instantiate above). The Triggers menu's
			// "delete" action calls :disable — see TriggerHandler's package
			// comment for why there's no Delete RPC.
			r.Post("/api/v1/workflows/triggers/{triggerId}:disable", triggerH.Disable)
			r.Post("/api/v1/workflows/triggers/{triggerId}:enable", triggerH.Enable)
		}

		// Broadcast node config pickers (#1394). Read-only proxies onto
		// dialogue-svc, forwarding the caller's own token — see the
		// dialogueclient package doc. They live under the static
		// /workflows/dialogue/ segment, a sibling of the {id} wildcard, the
		// same static-vs-param precedence /projects and /node-types rely on.
		if dialogueH != nil {
			r.Get("/api/v1/workflows/dialogue/channels", dialogueH.ListChannels)
			r.Get("/api/v1/workflows/dialogue/contact-groups", dialogueH.ListContactGroups)
			r.Get("/api/v1/workflows/dialogue/tags", dialogueH.ListTags)
			r.Get("/api/v1/workflows/dialogue/contacts", dialogueH.ListContacts)
		}

		// Files & Data node config pickers (#1407). Read-only proxies onto
		// files-svc, forwarding the caller's own token — see the filesclient
		// package doc. Same static-segment placement as the dialogue block
		// above.
		//
		// `documents` and `tables` are separate routes rather than one route
		// with a filter flag because they back two distinct catalog
		// `options_source` keys; see handlers.ListTables for why the MIME
		// allowlist must not move to the frontend.
		if filesH != nil {
			r.Get("/api/v1/workflows/files/corpora", filesH.ListCorpora)
			r.Get("/api/v1/workflows/files/documents", filesH.ListDocuments)
			r.Get("/api/v1/workflows/files/tables", filesH.ListTables)
		}
	})

	return r
}


