package server

// timeout_test.go proves the authenticated route group mounts a per-request
// httpserver.Timeout: a wedged downstream call (one that never returns on
// its own) must not hang the request indefinitely — the group's Timeout
// middleware cancels the request context after a bounded duration, so a
// ctx-aware handler (every handler in this codebase forwards a context
// derived from the request into its gRPC calls) unwinds promptly. Reuses
// the real JWT-signing harness from router_org_claim_test.go so the request
// goes through the FULL production auth stack, not a bypass.
//
// It also pins the composability invariant this group's Timeout depends on:
// authenticatedGroupTimeout must stay strictly greater than RunNode's own
// 35s runNodeDeadline (internal/handlers/execution.go), or a "test this
// node" run legitimately taking up to 35s would be truncated by this
// HTTP-level Timeout before RunNode's own client-side gRPC deadline ever
// gets a chance to fire and be mapped to an HTTP error.

import (
	"context"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"google.golang.org/grpc"

	"github.com/stretchr/testify/require"

	workflowv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/workflow/workflow/v1"
	"github.com/zenithflowinc/omnicore-platform/services/workflow-bff/internal/handlers"
)

// TestAuthenticatedGroupTimeout_ClearsRunNodeDeadline pins the invariant
// documented on authenticatedGroupTimeout: it must exceed the 35s
// runNodeDeadline execution.go sets explicitly on RunNode, with headroom,
// so a legitimately slow (up to 35s) node run is never truncated by this
// HTTP-level Timeout.
func TestAuthenticatedGroupTimeout_ClearsRunNodeDeadline(t *testing.T) {
	const runNodeDeadline = 35 * time.Second
	require.Greater(t, authenticatedGroupTimeout, runNodeDeadline,
		"authenticatedGroupTimeout must clear execution.go's runNodeDeadline with headroom")
}

// slowWorkflowClient's List blocks until its context is done, simulating a
// wedged/slow-responding workflow-svc that never replies on its own.
type slowWorkflowClient struct {
	fakeWorkflowClient
}

func (slowWorkflowClient) List(
	ctx context.Context,
	_ *workflowv1.ListRequest,
	_ ...grpc.CallOption,
) (*workflowv1.ListResponse, error) {
	<-ctx.Done()
	return nil, ctx.Err()
}

// TestAuthenticatedGroup_Timeout_BoundsWedgedRequest proves the
// authenticated route group's httpserver.Timeout mount actually bounds
// total request duration. The group timeout is shrunk to 50ms (see below)
// so the test is fast while still exercising the real New() wiring end to
// end.
func TestAuthenticatedGroup_Timeout_BoundsWedgedRequest(t *testing.T) {
	// Shrink the group Timeout directly rather than scaling it via
	// OMNICORE_TIMEOUT_SCALE: httpserver.Timeout reads that env var through
	// a process-wide sync.Once cache that locks in at the FIRST Timeout()
	// call in this test binary — which, in a full package run, is some
	// other test's call to New(), not this one. Overriding the package var
	// keeps this test fast and correct regardless of test run order.
	origTimeout := authenticatedGroupTimeout
	authenticatedGroupTimeout = 50 * time.Millisecond
	t.Cleanup(func() { authenticatedGroupTimeout = origTimeout })

	stub := newOrgClaimOIDCStub(t)
	verifier := newOrgClaimVerifier(t, stub, orgClaimTestAudience)
	token := stub.mintToken(t, orgClaimTestAudience, "org-a")

	h := New(Deps{Verifier: verifier, WorkflowH: handlers.NewWorkflowHandler(slowWorkflowClient{})})
	req := httptest.NewRequest(http.MethodGet, "/api/v1/workflows", nil)
	req.Header.Set("Authorization", "Bearer "+token)
	rec := httptest.NewRecorder()

	start := time.Now()
	done := make(chan struct{})
	go func() {
		h.ServeHTTP(rec, req)
		close(done)
	}()

	select {
	case <-done:
		elapsed := time.Since(start)
		require.Less(t, elapsed, 3*time.Second,
			"request took %v; want it bounded by the route Timeout (~50ms)", elapsed)
		require.NotEqual(t, http.StatusOK, rec.Code,
			"a wedged downstream must not resolve as a 200; body: %s", rec.Body.String())
	case <-time.After(5 * time.Second):
		t.Fatal("request did not complete within 5s — the authenticated route group has no bounded " +
			"per-request Timeout wired (httpserver.Timeout missing from server.go's New())")
	}
}



