package server

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

// TestNewRouter_SetsSecurityHeaders pins the lone-sibling gap found in the
// T19 retrofit audit: 10 of 13 BFFs mount platform/libs/go/security.Middleware
// on their router; workflow-bff did not. This test hits the always-registered
// /healthz route (no downstream / no JWT required) and asserts the four
// day-1 security headers are present with their canonical values (mirrored
// from platform/libs/go/security/headers_test.go and admin-bff's
// security_headers_test.go).
func TestNewRouter_SetsSecurityHeaders(t *testing.T) {
	h := New(Deps{})

	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/healthz", nil)
	h.ServeHTTP(rec, req)

	if got := rec.Header().Get("X-Content-Type-Options"); got != "nosniff" {
		t.Errorf("X-Content-Type-Options = %q, want %q — security.Middleware not applied", got, "nosniff")
	}
	if got := rec.Header().Get("X-Frame-Options"); got != "DENY" {
		t.Errorf("X-Frame-Options = %q, want %q — security.Middleware not applied", got, "DENY")
	}
	if got := rec.Header().Get("Strict-Transport-Security"); got != "max-age=31536000; includeSubDomains" {
		t.Errorf("Strict-Transport-Security = %q, want %q — security.Middleware not applied", got, "max-age=31536000; includeSubDomains")
	}
	if got := rec.Header().Get("Referrer-Policy"); got != "strict-origin-when-cross-origin" {
		t.Errorf("Referrer-Policy = %q, want %q — security.Middleware not applied", got, "strict-origin-when-cross-origin")
	}
}


