// TestMetricsWiring_MountsHandlerAndAppliesMiddleware covers the New()
// branches that mount deps.MetricsHandler at /metrics and apply
// deps.MetricsMiddleware to the router when both are non-nil. The generic
// behavior of the shared middleware/handler themselves (Prometheus format,
// counter increments, route-label bounding) is covered exhaustively in
// platform/libs/go/observability; this test only exercises this service's
// wiring of those deps into New().
func TestMetricsWiring_MountsHandlerAndAppliesMiddleware(t *testing.T) {
	middlewareCalled := false
	mw := func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			middlewareCalled = true
			next.ServeHTTP(w, r)
		})
	}

	h := New(Deps{
		MetricsHandler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.WriteHeader(http.StatusOK)
			_, _ = w.Write([]byte("metrics-ok"))
		}),
		MetricsMiddleware: mw,
	})

	req := httptest.NewRequest(http.MethodGet, "/metrics", nil)
	rr := httptest.NewRecorder()
	h.ServeHTTP(rr, req)

	if rr.Code != http.StatusOK {
		t.Fatalf("GET /metrics: status = %d, want 200", rr.Code)
	}
	body, _ := io.ReadAll(rr.Result().Body)
	if string(body) != "metrics-ok" {
		t.Errorf("body = %q, want %q — deps.MetricsHandler not mounted at /metrics", string(body), "metrics-ok")
	}
	if !middlewareCalled {
		t.Error("deps.MetricsMiddleware was not applied to the router")
	}
}

