// TestVerticalDisabled_Returns403 proves the exact middleware server.New
// mounts (featureflags.RequireVerticalEnabled(deps.FeatureFlagCache,
// "workflows")) rejects a request 403 vertical_disabled when the cache
// reports the vertical disabled — exercised directly against the middleware,
// the same isolation-testing pattern TestList_WrongAudience_Returns403 uses
// for auth.RejectAdminRoles (full JWKS/OIDC verification is out of scope for
// a BFF unit test; platform/libs/go/auth and platform/libs/go/featureflags
// own their own verifier/cache test suites). This pins that server.go wires
// the "workflows" vertical key (not "range" or some other typo) and that a
// disabled vertical never reaches next.
func TestVerticalDisabled_Returns403(t *testing.T) {
	cache := featureflags.NewCache(func(ctx context.Context) (map[string]bool, error) {
		return map[string]bool{"workflows": false}, nil
	}, time.Minute, nil)
	mw := featureflags.RequireVerticalEnabled(cache, "workflows")

	var nextCalled bool
	next := http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		nextCalled = true
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/api/v1/workflows", nil)
	rr := httptest.NewRecorder()
	mw(next).ServeHTTP(rr, req)

	if rr.Code != http.StatusForbidden {
		t.Fatalf("status = %d, want 403 vertical_disabled, body=%s", rr.Code, rr.Body.String())
	}
	if nextCalled {
		t.Fatal("next handler must NOT be called when the workflows vertical is disabled")
	}
}

