// TestProjectSubroutesAreNotShadowedByTheWorkflowIDWildcard is the routing
// risk #1351 introduces.
//
// /api/v1/workflows/{id} already existed, and every new project route lives
// under /api/v1/workflows/projects/... — which is a candidate match for that
// wildcard with id="projects". chi is trie-based and prefers a literal segment
// over a param, so it resolves correctly, but nothing said so out loud and
// nothing would catch a future refactor that mounts these under a Route()
// group in the wrong order.
//
// A 401 proves the path reached the AUTH gate, i.e. it is a registered route.
// A 404 would mean the wildcard swallowed it (WorkflowHandler.Get would have
// been asked for a workflow literally named "projects") or that it was never
// registered at all.
func TestProjectSubroutesAreNotShadowedByTheWorkflowIDWildcard(t *testing.T) {
	h := New(Deps{
		WorkflowH: handlers.NewWorkflowHandler(fakeWorkflowClient{}),
		ProjectH:  handlers.NewProjectHandler(fakeProjectClient{}),
	})

	for _, tc := range []struct{ method, path string }{
		{http.MethodGet, "/api/v1/workflows/projects"},
		{http.MethodPost, "/api/v1/workflows/projects"},
		{http.MethodGet, "/api/v1/workflows/projects/p1"},
		{http.MethodPatch, "/api/v1/workflows/projects/p1"},
		{http.MethodDelete, "/api/v1/workflows/projects/p1"},
		{http.MethodGet, "/api/v1/workflows/projects/p1/workflows"},
		{http.MethodGet, "/api/v1/workflows/projects/p1/members"},
		{http.MethodPut, "/api/v1/workflows/projects/p1/members/u1"},
		{http.MethodDelete, "/api/v1/workflows/projects/p1/members/u1"},
		// The tag vocabulary sits beside them and has the same exposure.
		{http.MethodGet, "/api/v1/workflows/tags"},
	} {
		t.Run(tc.method+" "+tc.path, func(t *testing.T) {
			req := httptest.NewRequest(tc.method, tc.path, strings.NewReader("{}"))
			rr := httptest.NewRecorder()
			h.ServeHTTP(rr, req)

			if rr.Code != http.StatusUnauthorized {
				t.Fatalf("status = %d, want 401 (route registered and auth-gated); "+
					"404 here means the /workflows/{id} wildcard shadowed it", rr.Code)
			}
		})
	}
}

